use std::cmp::Ordering;

fn in_ranges<T: Copy>(ranges: &[(u16, u16, T)], c: u16) -> Option<T> {
    ranges
        .binary_search_by(|&(lo, hi, _)| {
            if hi < c {
                Ordering::Less
            } else if lo > c {
                Ordering::Greater
            } else {
                Ordering::Equal
            }
        })
        .ok()
        .map(|i| ranges[i].2)
}

